description:
Implement `DeepRequired<T>` — a recursive type that removes optionality from all properties at every depth level.

**Example:**
```ts
type Config = DeepRequired<{ host?: string; db?: { port?: number } }>;
// { host: string; db: { port: number } }
```

starter_code:
export type DeepRequired<T> = // your type here

export function ensureComplete<T>(obj: DeepRequired<T>): DeepRequired<T> {
  return obj;
}

test_suite:
test('ensureComplete returns same object', () => {
  const obj = { host: 'localhost', db: { port: 5432 } };
  expect(ensureComplete(obj)).toEqual(obj);
});

test('type-level: top-level props are required', () => {
  type T = DeepRequired<{ a?: number; b?: string }>;
  type Check = T extends { a: number; b: string } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: nested props are required', () => {
  type T = DeepRequired<{ inner?: { x?: number } }>;
  type Check = T extends { inner: { x: number } } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: matches Required at top level', () => {
  type T = { a?: string; b?: number };
  type Check = DeepRequired<T> extends Required<T> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

// __hidden__
test('type-level: primitives pass through unchanged', () => {
  type T = DeepRequired<number>;
  const check: T = 42;
  expect(check).toBe(42);
});

solution:
export type DeepRequired<T> = T extends object ? { [K in keyof T]-?: DeepRequired<T[K]> } : T;

export function ensureComplete<T>(obj: DeepRequired<T>): DeepRequired<T> {
  return obj;
}
